import React from "react";
import { motion } from "framer-motion";
import { ArrowLeft } from "lucide-react";
import { Link } from "react-router-dom";
import Collections from "../components/Collections";
import Footer from "../components/Footer";
import { CircularGallery } from "../components/circular-gallery";
import { COLLECTIONS } from "../types";

export default function CollectionsPage() {
  return (
    <>
      {/* Hero Section for Collections Page */}
      <section className="relative min-h-[60vh] flex items-center justify-center overflow-hidden bg-gray-900">
        {/* Background Image */}
        <div className="absolute inset-0">
          <img
            src="https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=1600"
            alt="Collections"
            className="w-full h-full object-cover opacity-40"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-black/40 to-black/80" />
        </div>

        {/* Content */}
        <div className="relative z-10 text-center px-6 max-w-4xl mx-auto">
          {/* Back Button */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="mb-8"
          >
            <Link
              to="/"
              className="inline-flex items-center gap-2 text-white/70 hover:text-amber-400 transition-colors text-sm font-medium group"
            >
              <motion.div
                className="group-hover:-translate-x-1 transition-transform"
              >
                <ArrowLeft size={18} />
              </motion.div>
              Back to Home
            </Link>
          </motion.div>

          {/* Overline */}
          <motion.div
            className="flex items-center justify-center gap-4 mb-8"
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: 0.3 }}
          >
            <div className="h-px w-16 bg-gradient-to-r from-transparent to-amber-400" />
            <span className="text-sm font-bold tracking-[0.2em] uppercase text-amber-400">
              D Sajawat
            </span>
            <div className="h-px w-16 bg-gradient-to-l from-transparent to-amber-400" />
          </motion.div>

          {/* Title */}
          <motion.h1
            className="text-5xl md:text-6xl lg:text-7xl font-bold text-white mb-6"
            style={{ fontFamily: "Georgia, serif" }}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4, duration: 0.8 }}
          >
            Our{" "}
            <span className="text-amber-400">Collections</span>
          </motion.h1>

          {/* Subtitle */}
          <motion.p
            className="text-lg md:text-xl text-white/70 max-w-2xl mx-auto"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.6 }}
          >
            Explore our curated range of premium fabrics, drapes, and event
            essentials crafted for unforgettable celebrations
          </motion.p>
        </div>

        {/* Scroll Indicator */}
        <motion.div
          className="absolute bottom-8 left-1/2 -translate-x-1/2"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1 }}
        >
          <motion.div
            className="w-6 h-10 border-2 border-white/30 rounded-full flex items-start justify-center p-1.5"
            animate={{ borderColor: ["rgba(255,255,255,0.3)", "rgba(255,255,255,0.6)", "rgba(255,255,255,0.3)"] }}
            transition={{ duration: 2, repeat: Infinity }}
          >
            <motion.div
              className="w-1.5 h-1.5 bg-amber-400 rounded-full"
              animate={{ y: [0, 12, 0] }}
              transition={{ duration: 1.5, repeat: Infinity }}
            />
          </motion.div>
        </motion.div>
    </section>

    {/* Circular Gallery Showcase */}
    <section className="relative py-20 lg:py-32 bg-gray-950 overflow-hidden">
      <div className="container mx-auto px-6">
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <span className="text-sm font-bold tracking-[0.2em] uppercase text-amber-400">
            Featured Collections
          </span>
          <h2 className="mt-4 text-4xl md:text-5xl lg:text-6xl font-bold text-white" style={{ fontFamily: "Georgia, serif" }}>
            Explore Our <span className="text-amber-400">Range</span>
          </h2>
          <p className="mt-4 text-lg text-white/60 max-w-2xl mx-auto">
            Swipe or scroll to discover our premium fabric collections in an immersive 360° view
          </p>
        </motion.div>

        <div style={{ height: "600px", position: "relative" }}>
          <CircularGallery
            bend={1}
            textColor="#ffffff"
            borderRadius={0.05}
            scrollEase={0.05}
            font="bold 24px Orbitron"
            scrollSpeed={2}
            images={COLLECTIONS.map((c) => c.image)}
            labels={COLLECTIONS.map((c) => c.title)}
          />
        </div>

        <motion.div
          className="absolute bottom-10 left-1/2 -translate-x-1/2 text-center"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.5 }}
        >
          <p className="text-white/50 text-sm uppercase tracking-[0.2em]">
            Scroll / Swipe to rotate
          </p>
        </motion.div>
      </div>
    </section>

      {/* Collections Grid */}
      <Collections />

      {/* Footer */}
      <Footer />
    </>
  );
}
